    Bug 1884523 - Wait for messages to actually be sent in test_mailTelemetry.js. r=mkmelin

    In this test we're sending all of the messages at once instead of sequentially. That's probably
    not helping reliability, and the SMTP server is still trying to do things after the test ends.

    Differential Revision: https://phabricator.services.mozilla.com/D267900

diff --git a/mailnews/compose/test/unit/test_mailTelemetry.js b/mailnews/compose/test/unit/test_mailTelemetry.js
index a74ba9bab34..d74661f85e2 100644
--- a/mailnews/compose/test/unit/test_mailTelemetry.js
+++ b/mailnews/compose/test/unit/test_mailTelemetry.js
@@ -24,6 +24,7 @@ const deliveryListener = {
         "mails_sent must be correct"
       );
     }
+    this.deferred.resolve();
   },
 };

@@ -57,6 +58,7 @@ add_task(async function test_mails_sent() {
       .msgGenerateMessageId(identity, null);

     for (let i = 0; i < NUM_MAILS; i++) {
+      deliveryListener.deferred = Promise.withResolvers();
       smtpServer.sendMailMessage(
         testFile,
         MailServices.headerParser.parseEncodedHeaderW(kTo),
@@ -69,6 +71,7 @@ add_task(async function test_mails_sent() {
         messageId,
         deliveryListener
       );
+      await deliveryListener.deferred.promise;
     }
   } catch (e) {
     do_throw(e);
